const items = $input.first().json.results || [];
if (items.length === 0) return [];

const widgets = [
  {
    textParagraph: {
      text: `<b>👀 Peer Review Attention Required:</b> <b>${items.length} tasks</b> are in flight awaiting specification, code, or design review signoff.`
    }
  }
];

for (const it of items.slice(0, 5)) {
  const props = it.properties || {};
  const title = (props['Task Name']?.title || []).map(t => t.plain_text).join('') || 'Untitled';
  const priority = props['Priority']?.select?.name || 'P3 - Medium';
  const complexity = props['Complexity']?.select?.name || '⭐ 3';
  const team = props['Team / Pod']?.select?.name || 'Engineering';
  const url = it.url || `https://notion.so/${it.id.replace(/-/g, '')}`;

  widgets.push({
    decoratedText: {
      topLabel: `In Review | ${priority} (${complexity})`,
      text: `<b>${title}</b>`,
      bottomLabel: `Pod: ${team}`,
      button: {
        text: 'REVIEW TASK',
        onClick: {
          openLink: {
            url
          }
        }
      }
    }
  });
}

const googleChatPayload = {
  cardsV2: [
    {
      cardId: 'wasp_review_queue_' + Date.now(),
      card: {
        header: {
          title: '🐝 WASP Engine — Peer Review Queue',
          subtitle: `${items.length} Deliverables Awaiting Signoff`,
          imageUrl: 'https://cdn-icons-png.flaticon.com/512/1006/1006771.png',
          imageType: 'CIRCLE'
        },
        sections: [
          {
            header: 'Tasks in Peer Review Pipeline',
            widgets
          }
        ]
      }
    }
  ]
};

return [{
  json: {
    count: items.length,
    googleChatPayload
  }
}];
